// ========================================
// 场景 1: 谓词下推失效 —— 函数包裹
// ========================================
// 不下推: date() 包裹分区列，Parquet 无法利用 row group 统计
spark.sql("""
  SELECT user_id, amount
  FROM orders
  WHERE date(event_ts) = '2026-06-13'
""").explain("formatted")
// FileScan parquet … PartitionFilters: [], PushedFilters: []
// → 全表扫描

// 修复: 直接对原始列做范围过滤
spark.sql("""
  SELECT user_id, amount
  FROM orders
  WHERE event_ts >= '2026-06-13 00:00:00'
    AND event_ts <  '2026-06-14 00:00:00'
""").explain("formatted")
// FileScan parquet … PartitionFilters: [isnotnull(dt), (dt = 2026-06-13)],
//                  PushedFilters: [IsNotNull(event_ts), GreaterThanOrEqual(event_ts, ...)]

// ========================================
// 场景 2: 隐式类型转换阻断下推
// ========================================
// int_col = '123' 会触发 cast(int_col as string)，阻断下推
spark.sql("""
  SELECT * FROM t WHERE int_col = '123'
""").explain("formatted")
// 修复: 匹配类型
spark.sql("""
  SELECT * FROM t WHERE int_col = 123
""").explain("formatted")

// ========================================
// 场景 3: Join 策略对比
// ========================================
// 关闭 AQE 看编译期决策
spark.conf.set("spark.sql.adaptive.enabled", "false")
val big   = spark.table("fact_orders")  // 大表
val small = spark.table("dim_user")     // 小表

// 强制广播: 明确走 BroadcastHashJoin
big.join(broadcast(small), "user_id").explain("formatted")
// BroadcastHashJoin [user_id], Inner, BuildRight
//   +- BroadcastExchange HashedRelationBroadcastMode(...)

// 开启 AQE: 编译期走 SMJ，运行时可能被 AQE 降级成 BHJ
spark.conf.set("spark.sql.adaptive.enabled", "true")
big.join(small, "user_id").explain("formatted")
// Physical Plan 可能出现:
//   AdaptiveSparkPlan isFinalPlan=true
//     +- == Final Plan ==
//        BroadcastHashJoin (was SortMergeJoin)
